use std::collections::HashMap;use super::kernel::Kernel;use ndarray::{ArrayView1, Array1};use crate::dual_number::Dual;use crate::constraint::constraint::Constraint;use std::f64::consts::PI;use extendr_api::prelude::*;use crate::dataset::DataManager;#[derive(Debug)]pub struct PeriodicKernel {    sigma: f64,    lengthscales: Array1<f64>,    periods: Array1<f64>,    n_params: usize,    operating_columns: Vec<usize>,    fixed_periods : bool,    d: usize}impl PeriodicKernel {    pub fn new(operating_columns: Vec<usize>, kwargs : HashMap<&str, Robj>, dataset : &dyn DataManager) -> Self {        let periods = kwargs.get("periods")            .map(|periods| periods.as_real_vector().unwrap())            .map(|x| Array1::from(x) * dataset.get_x_scale_factor());        let d = operating_columns.len();        let fixed_periods = periods.is_some();        let n_params = if fixed_periods {            d + 1        } else {            2*d + 1        };        let periods = match periods {            Some(periods) => {periods}            None => {Array1::ones(d)}        };        Self {            sigma: 1.0,            lengthscales: Array1::ones(d),            periods,            n_params,            operating_columns,            fixed_periods,            d        }    }}impl Kernel for PeriodicKernel {    fn rec_constraint(&self) -> Vec<Constraint> {        vec![Constraint::new_positive_sp(); self.n_params]    }    fn num_params(&self) -> usize {        self.n_params    }    fn set_params(&mut self, params: &[f64]) {        let (sigma, remainder) = params.split_at(1);        self.sigma = sigma[0];        if self.fixed_periods {            self.lengthscales = Array1::from(remainder.to_owned());        } else {            let (periods, lengthscales) = remainder.split_at(self.d);            self.periods = Array1::from(periods.to_owned());            self.lengthscales = Array1::from(lengthscales.to_owned());        }    }    fn calc(&self, x: ArrayView1<f64>, y: ArrayView1<f64>, gradient: bool) -> Dual {        let thetas: Vec<f64> = self            .operating_columns            .iter()            .map(|i| (x[*i] - y[*i]) * PI / self.periods[*i])            .collect();        let ratio_sum: f64 = thetas.iter()            .zip(self.lengthscales.iter())            .map(|(theta, denom)| 2.0 * theta.sin().powi(2) / (denom.powi(2)))            .sum();        let result = self.sigma.powi(2) * ((-1.0 * ratio_sum).exp());        if !gradient {            return Dual::from(result)        };        let mut grad_lengthscales: Vec<f64> = thetas.iter()            .zip(self.lengthscales.iter())            .map(|(theta, l)| result * 4.0 * (theta.sin().powi(2)) / (l.powi(3)))            .collect();        let grad_sigma = 2.0 * result / self.sigma;        grad_lengthscales.insert(0, grad_sigma);        if ! self.fixed_periods {            let grad_periods : Vec<f64> = thetas.iter()                .zip(self.lengthscales.iter().zip(self.periods.iter()))                .map(|(theta, (lengthscale, period))| result * (2.0*theta).sin() * 2.0 * theta / (lengthscale.powi(2) * period)).collect();            grad_lengthscales.extend(grad_periods);        }        Dual::from((result, Array1::from_vec(grad_lengthscales)))    }    fn children(&self) -> &[Box<dyn Kernel>] {        &[]    }    fn describe(&self) -> String {        "RBF Kernel".to_string()    }    fn log_prior(&self, gradient : bool) -> Dual {        todo!()    }}